cd "C:/visual projects/sns-ref/data" && python - <<'E'
import json,sys,collections
sys.stdout.reconfigure(encoding='utf-8')
d=json.load(open('skilltree.json',encoding='utf-8'))
for mode in ('classic','enhanced'):
    L=d[mode]
    print(mode,{k:L[5][k] for k in ('id','name','type','value','cost','parent','loc','img')})
    hid=[n for n in L if n['img'] is None or n['img']<0]
    print('hidden',len(hid), 'par len dist',collections.Counter(len(n['parent']) for n in L))
    ids={n['id']:n for n in L}
    adj=collections.defaultdict(set)
    for n in L:
        for p in n['parent']:
            if p>=0: adj[n['id']].add(p); adj[p].add(n['id'])
    typ={17:'STR',18:'DEX',19:'MAG',20:'WIS',21:'END',22:'WILL',23:'bagHP',24:'bagMP'}
    starts={'knight':(0,50),'mage':(42,262),'paladin':(3,50),'thief':(4,),'cleric':(6,36),'hunter':(8,13)}
    for nm,ss in starts.items():
        dist={s:0 for s in ss}; q=list(ss)
        while q:
            u=q.pop(0)
            for v in adj[u]:
                if v not in dist: dist[v]=dist[u]+1; q.append(v)
        out={}
        for R in (4,8,12):
            c=collections.Counter(typ[ids[v]['type']] for v,dd in dist.items() if dd<=R and ids[v]['type'] in typ and ids[v]['img'] not in (None,-1))
            out[R]=dict(c)
        print(nm,[ (s,ids[s]['name']) for s in ss],out)
    # global: names for type<17 ranks
    print(sorted({(n['type'],n['name'].rsplit('_',1)[0]) for n in L if n['type']<17 or n['type']>24}))
    print('total stat nodes visible',sum(1 for n in L if n['type'] in typ and n['img'] not in (None,-1)))
E

