	internal float GetElementalFactor(Player p)
	{
		LootDef lootDef = LootCatalog.category[category].loot[catalogIdx];
		if (lootDef.flags >= 1 && lootDef.flags <= 6)
		{
			float num = lootDef.values[7];
			if (num <= 0f)
			{
				num = 0.5f;
			}
			return num;
		}
		return 0f;
	}

	internal float GetLockedElementalDamageVal(int value, Player p, PlayerStats stats, bool twoHanded, InvLoot replaceLoot)
	{
		float value2 = GetValue(value, p);
		LootDef lootDef = LootCatalog.category[category].loot[catalogIdx];
		float num = 50f;
		int num2 = 1;
		num2 = PlayerStats.GetSplitStats(lootDef);
		num = PlayerStats.GetNewSoftcap(num2);
		float num3 = stats.GetEquipAdjustedStat(0, replaceLoot);
		if (twoHanded)
		{
			num3 *= 1f + 0.5f / (float)num2;
		}
		num3 = ((num3 < num) ? num3 : num) + ((num3 > num) ? ((num3 - num) * 0.1f) : 0f);
		float cappedStat = stats.GetCappedStat40(2, replaceLoot, num);
		float cappedStat2 = stats.GetCappedStat40(4, replaceLoot, num);
		float cappedStat3 = stats.GetCappedStat40(5, replaceLoot, num);
		if (num3 < 0f)
		{
			return 0f;
		}
		if (cappedStat < 0f)
		{
			return 0f;
		}
		if (cappedStat2 < 0f)
		{
			return 0f;
		}
		if (cappedStat3 < 0f)
		{
			return 0f;
		}
		float elementalFactor = GetElementalFactor(p);
		bool flag = lootDef.flags >= 1 && lootDef.flags <= 6;
		float num4 = (flag ? 2f : 1f) + num3 * lootDef.values[1] * 1f / (num * 0.8f) + cappedStat * lootDef.values[2] * 1f / (num * 0.8f) + cappedStat2 * lootDef.values[4] * 1f / (num * 0.8f) + cappedStat3 * lootDef.values[3] * 1f / (num * 0.8f);
		switch (lootDef.flags)
		{
		case 1:
		case 2:
		case 6:
			num4 += stats.GetCappedStat40(4, num) * lootDef.values[9] * 1f / (num * 0.8f);
			break;
		case 5:
			num4 += stats.GetCappedStat40(5, num) * lootDef.values[9] * 1f / (num * 0.8f);
			break;
		case 3:
			num4 += stats.GetCappedStat40(5, num) * lootDef.values[2] * 1f / (num * 0.8f);
			break;
		}
		value2 *= num4;
		switch (value)
		{
		case 0:
			if (flag)
			{
				return value2 * (1f - elementalFactor);
			}
			return value2;
		case 6:
			if (lootDef.flags == 1)
			{
				return value2 * elementalFactor;
			}
			return 0f;
		case 7:
			if (lootDef.flags == 2)
			{
				return value2 * elementalFactor;
			}
			return 0f;
		case 9:
			if (lootDef.flags == 3)
			{
				return value2 * elementalFactor;
			}
			return 0f;
		case 12:
			if (lootDef.flags == 5)
			{
				return value2 * elementalFactor;
			}
			return 0f;
		case 13:
			if (lootDef.flags == 6)
			{
				return value2 * elementalFactor;
			}
			return 0f;
		default:
			return 0f;
		}
	}

