# worked weapon calcs
def sc(v,C): return v if v<=C else C+0.1*(v-C)
def dmg(atk,ks,stats,C,two=False,n=1):
    M=1
    for k,s in zip(ks,stats):
        if two: s=s*(1+0.5/n)
        M+=sc(s,C)*k/(0.8*C)
    return atk*M,M
